	const footerLines = [];
	const breakingNote = opts.breakingNote.trim();
	if (opts.breaking && breakingNote !== "") footerLines.push(`BREAKING CHANGE: ${breakingNote}`);
	const footer = opts.footer.trim();
	if (footer !== "") footerLines.push(footer);
